PREFIX dc: <http://purl.org/dc/elements/1.1/>

SELECT (COUNT(DISTINCT ?contributor) AS ?numContributors)
WHERE {
    ?game dc:title "Cyberpunk 2077" .
    ?game dc:contributor ?contributor .
}

